result:
    .c_radio{
		&.on{
			padding: 0 15px;
			.c_label{
				color: #999999;
				font-size: 12px;
			}
			/deep/.ivu-radio-wrapper{
				margin: 5px 25px 15px 0;
			}
		}
        .c_row-item{
           align-items: unset;
        }
        .c_label{
            color: #000;
            margin-right: 15px;
            margin-top: 4px;
            &.on{
              text-align: right;
              color: #666;
            }
        }
        /deep/.ivu-radio-wrapper{
          margin: 5px 25px 5px 0;
		  &:nth-last-child(1){
			  margin-right: 0;
		  }
        }
        /deep/.ivu-radio{
            margin-right: 6px;
        }
    }
